function clearAllMonths(){if(!confirm('Zerar os lançamentos de todos os meses? Os meses, bancos, dívidas, metas e assinaturas serão mantidos.'))return;S.keys.forEach(k=>{let m=S.months[k]||{};S.months[k]={salary:+S.profile?.salarioBase||0,salaryManual:false,bonus:+S.profile?.bonusBase||0,valeRefeicao:0,valeAlimentacao:0,valeReembolso:0,gastos:[],fixos:[],parcelas:[],reserva:0,rendaFixa:0,investimentos:[],vrPeriodos:[],esperado:{},aportesMetas:[],nomeMes:m.nomeMes||''}});save();go('painel')}
function notifyDueToday(){let todayKey=dateKey(new Date()),due=[];S.keys.forEach(k=>{let m=M(k);[...(m.gastos||[]),...(m.fixos||[]),...(m.parcelas||[])].forEach(r=>{if(dateKey(rowDueDate(k,r))===todayKey&&!r.pago)due.push(r)})});if(due.length)window.setTimeout(()=>alert('Hoje você tem '+due.length+' compromisso(s) financeiro(s):\n'+due.map(x=>'• '+x.nome+' — '+brl(x.valor)).join('\n')),600)}
function openSpendingAdvisor(){let greetingHour=new Date().getHours(),dayGreeting=greetingHour<12?'Bom dia':greetingHour<18?'Boa tarde':'Boa noite',displayName=S.profile?.chamado||S.profile?.nome||'';let old=document.getElementById('spending-advisor');if(old)old.remove();let d=document.createElement('dialog');d.id='spending-advisor';d.className='finance-dialog advisor-dialog advisor-chat-dialog';let k=S.keys.includes(cur)?cur:(S.keys.includes(today)?today:S.keys[0]),c=calc(k),answers={},steps=[{key:'item',question:'O que você está pensando em comprar?',hint:'Pode me contar o que é. Ex.: um celular, uma passagem, uma compra de mercado.',type:'text',placeholder:'O que pretende comprar?'},{key:'valor',question:'Quanto você pretende gastar?',hint:'Assim consigo comparar o valor com o seu orçamento.',type:'number',placeholder:'Valor em reais'},{key:'cat',question:'Em qual categoria essa compra entra?',hint:'Escolha a categoria que melhor representa essa despesa.',type:'select',options:[...new Set([...S.cats,'Alimentação / Refeição','Transporte','Saúde','Educação'])]},{key:'tipo',question:'Como pretende pagar?',hint:'A forma de pagamento muda a análise.',type:'select',options:['Débito','Crédito','Pix','Boleto','Vale-refeição / alimentação','Auxílio home office','Auxílio']},{key:'essencial',question:'Essa compra é essencial neste momento?',hint:'Quero entender se é uma necessidade ou se pode esperar.',type:'select',options:[{value:'sim',label:'Sim, é necessário'},{value:'nao',label:'Não, posso esperar'}]},{key:'prazo',question:'Quando pretende fazer essa compra?',hint:'Isso ajuda a considerar seus próximos compromissos.',type:'select',options:[{value:'agora',label:'Agora'},{value:'proximo',label:'No próximo mês'},{value:'tres',label:'Daqui a 3 meses'}]}],step=0;d.innerHTML='<div class="dialog-head"><div><p class="eyebrow">CONSELHEIRO FINANCEIRO</p><h2>Vamos conversar sobre essa compra?</h2></div><button class="button secondary" data-close>×</button></div><div class="advisor-chat-intro">Olá'+(displayName?', '+esc(displayName):'')+'! '+dayGreeting+', tudo bem? Vou fazer algumas perguntas para entender sua situação e avaliar o impacto dessa compra no seu orçamento.</div><div class="advisor-chat-messages" aria-live="polite"></div><form class="advisor-chat-reply"></form>';document.body.appendChild(d);let messages=d.querySelector('.advisor-chat-messages'),reply=d.querySelector('.advisor-chat-reply');const bubble=(who,html)=>{let el=document.createElement('div');el.className='advisor-chat-bubble '+(who==='user'?'user':'assistant');el.innerHTML=html;messages.appendChild(el);messages.scrollTop=messages.scrollHeight};const ask=()=>{let q=steps[step];bubble('assistant','<b>'+esc(q.question)+'</b><small>'+esc(q.hint)+'</small>');let control=q.type==='select'?'<select name="answer" required><option value="">Selecione uma opção</option>'+q.options.map(o=>{let value=typeof o==='string'?o:o.value,label=typeof o==='string'?o:o.label;return '<option value="'+esc(value)+'">'+esc(label)+'</option>'}).join('')+'</select>':'<input name="answer" type="'+q.type+'" '+(q.type==='number'?'min="0.01" step=".01"':'')+' placeholder="'+esc(q.placeholder)+'" required>';reply.innerHTML=control+'<button class="button primary" type="submit">Enviar resposta</button>';reply.querySelector('[name=answer]').focus()};const finish=()=>{let amount=+answers.valor||0,type=answers.tipo,essential=answers.essencial==='sim',benefit=['Alimentação / Refeição','Vale-refeição / alimentação'].includes(type)?c.beneficiosRestantes.alimentacao:['Auxílio home office','Auxílio'].includes(type)?c.beneficiosRestantes.homeOffice:0,usesBenefit=['Alimentação / Refeição','Vale-refeição / alimentação','Auxílio home office','Auxílio'].includes(type),available=usesBenefit?benefit:c.saldo,room=available-amount,hasDebt=S.debts.some(x=>(+x.valor||0)>0),headline,explain;if(usesBenefit&&amount>benefit){headline='ESPERE OU REDUZA O VALOR';explain='O benefício disponível é '+brl(benefit)+'. O excedente de '+brl(amount-benefit)+' sairia do saldo em dinheiro.'}else if(room<0){headline=essential?'PROCURE UMA ALTERNATIVA MAIS BARATA':'MELHOR ADIAR';explain='Com base no saldo disponível estimado ('+brl(available)+'), a compra deixaria o saldo em '+brl(room)+'.'}else if(!essential&&room<Math.max(100,available*.2)){headline='PODE CABER, MAS COM CAUTELA';explain='A compra deixaria '+brl(room)+'. Considere manter uma margem para imprevistos.'}else{headline='PARECE CABER NO ORÇAMENTO';explain='Depois da compra, a estimativa seria '+brl(room)+'. Confira vencimentos e despesas ainda não lançadas.'}if(hasDebt&&amount>Math.max(0,c.saldo)*.25)explain+=' Você tem dívidas em aberto; compare a compra com os próximos vencimentos.';if(answers.prazo==='proximo')explain+=' Você pretende esperar até o próximo mês: confira a projeção antes de comprar.';if(answers.prazo==='tres')explain+=' Para estimar daqui a três meses, preencha as entradas e despesas previstas desse período.';bubble('assistant','<b>Minha análise sobre '+esc(answers.item)+'</b><div class="advisor-chat-verdict">'+headline+'</div><p>'+esc(explain)+'</p><small>Estimativa baseada nos dados de '+esc(full(k))+'. Não é uma garantia; despesas ainda não cadastradas podem alterar o resultado.</small>');reply.innerHTML='<button type="button" class="button secondary" data-restart>Começar outra análise</button>';reply.querySelector('[data-restart]').onclick=()=>{step=0;answers={};messages.innerHTML='';bubble('assistant','Claro! Vamos analisar outra compra.');ask()}};reply.onsubmit=e=>{e.preventDefault();let value=reply.querySelector('[name=answer]').value.trim();if(!value)return;let q=steps[step];answers[q.key]=value;let shown=q.key==='valor'?brl(+value):q.key==='essencial'?(value==='sim'?'Sim, é necessário':'Não, posso esperar'):q.key==='prazo'?({agora:'Agora',proximo:'No próximo mês',tres:'Daqui a 3 meses'}[value]||value):value;bubble('user',esc(shown));step++;if(step<steps.length)ask();else finish()};d.querySelector('[data-close]').onclick=()=>d.close();d.addEventListener('close',()=>d.remove(),{once:true});d.showModal();ask()}
const investmentFormat=n=>(+n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
async function refreshInvestmentRates(force=false){
 const key='financas.investmentRates.v1',now=Date.now();
 try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(!force&&saved&&now-saved.fetchedAt<86400000){investmentRates={...saved,error:false};if(cur==='investimentos')render();return}
 const get=async(code)=>{const u='https://api.bcb.gov.br/dados/serie/bcdata.sgs.'+code+'/dados/ultimos/2?formato=json';const r=await fetch(u,{cache:'no-store'});if(!r.ok)throw new Error('BCB indisponível');const a=await r.json();const x=a[a.length-1];if(!x)throw new Error('Sem dados');return{value:+String(x.valor).replace(',','.'),date:x.data}};
 const [selic,cdi,ipca]=await Promise.all([get(432),get(4389),get(433)]);
 investmentRates={selic,cdi,ipca,updated:new Date().toISOString(),fetchedAt:now,error:false};localStorage.setItem(key,JSON.stringify(investmentRates));
 }catch(e){const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved)investmentRates={...saved,error:true};else investmentRates={...investmentRates,error:true}}
 if(cur==='investimentos')render();
}
function investmentTax(days){return days<=180?.225:days<=360?.20:days<=720?.175:.15}
function investmentProjection(){
 const amount=Math.max(0,+($('#inv-amount')?.value||1000)),months=Math.max(1,+($('#inv-months')?.value||12)),pct=Math.max(1,+($('#inv-cdi')?.value||100));
 const cdi=investmentRates.cdi?.value||0,selic=investmentRates.selic?.value||0,days=months*365/12,ir=investmentTax(days);
 const calc=(annual)=>{const gross=amount*Math.pow(1+annual/100,months/12)-amount;return{gross,net:gross*(1-ir)}};
 const c=calc(cdi*pct/100),t=calc(selic),p=amount*(Math.pow(1+(selic>8.5?.005:(selic*.7/100/12)),months)-1);
 return{amount,months,cdi,pct,selic,cdiResult:c,tesouro:t,poupanca:p,ir};
}
function updateInvestmentProjection(){const o=$('#investment-results');if(!o)return;const x=investmentProjection();o.innerHTML='<div class="investment-result"><span>CDB · '+x.pct+'% do CDI</span><strong>'+investmentFormat(x.amount+x.cdiResult.net)+'</strong><small>Ganho líquido estimado: '+investmentFormat(x.cdiResult.net)+'</small></div><div class="investment-result"><span>Tesouro Selic · estimativa</span><strong>'+investmentFormat(x.amount+x.tesouro.net)+'</strong><small>Ganho líquido estimado: '+investmentFormat(x.tesouro.net)+'</small></div><div class="investment-result"><span>Poupança · estimativa simplificada</span><strong>'+investmentFormat(x.amount+x.poupanca)+'</strong><small>Ganho estimado: '+investmentFormat(x.poupanca)+'</small></div><p class="investment-note">Estimativas brutas de premissas constantes. CDB e Tesouro usam IR regressivo estimado; Tesouro considera Selic constante e não inclui custódia, spread ou marcação a mercado. Poupança usa a regra simplificada de remuneração básica, sem TR. Não são ofertas nem garantia de retorno.</p>'}
function investmentsView(){
 const rate=(x,suffix='% a.a.')=>x?x.value.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})+suffix:'—';
 const date=x=>x?.date||'Aguardando dado';
 const freshness=investmentRates.updated?'Atualizado em '+new Date(investmentRates.updated).toLocaleString('pt-BR'):(investmentRates.error?'Não foi possível consultar a fonte':'Consultando fontes oficiais…');
 const view=head('INVESTIMENTOS','Investir com informação.','Compare cenários, entenda os riscos e simule antes de decidir.',button('↻ Atualizar dados','refresh-investments','secondary'))+
 '<section class="investment-status"><div><b>Dados de referência</b><span>'+esc(freshness)+'</span></div><span class="investment-live">'+(investmentRates.error?'Último dado disponível / falha na consulta':'Atualização automática diária')+'</span></section>'+
 '<section class="investment-indicators"><article><span>Meta Selic</span><strong>'+(investmentRates.selic?rate(investmentRates.selic):'—')+'</strong><small>Referência: '+date(investmentRates.selic)+'</small></article><article><span>CDI</span><strong>'+(investmentRates.cdi?rate(investmentRates.cdi):'—')+'</strong><small>Referência: '+date(investmentRates.cdi)+'</small></article><article><span>IPCA mensal</span><strong>'+(investmentRates.ipca?rate(investmentRates.ipca,'%'):'—')+'</strong><small>Referência: '+date(investmentRates.ipca)+'</small></article></section>'+
 '<section class="panel investment-calculator"><div class="panel-head"><div><p class="eyebrow">SIMULADOR</p><h2>Quanto seu dinheiro pode render?</h2><p>Altere o valor e o prazo para comparar cenários.</p></div></div><div class="investment-fields"><label>Valor inicial (R$)<input id="inv-amount" data-change="investment-input" type="number" min="1" step="0.01" value="1000"></label><label>Prazo (meses)<input id="inv-months" data-change="investment-input" type="number" min="1" max="600" value="12"></label><label>CDB (% do CDI)<input id="inv-cdi" data-change="investment-input" type="number" min="1" max="300" value="100"></label></div><div id="investment-results" class="investment-results"></div></section>'+
 '<section class="panel"><div class="panel-head"><div><p class="eyebrow">COMO ANALISAR</p><h2>Não olhe só para a rentabilidade</h2></div></div><div class="investment-risk-grid"><article><b>Liquidez</b><p>Quando você pode resgatar? Liquidez diária não é a mesma coisa que vencimento longo.</p></article><article><b>Risco de crédito</b><p>Quem deve pagar? CDB, LCI e LCA podem ter cobertura do FGC dentro dos limites e regras vigentes; fundos e títulos públicos têm riscos diferentes.</p></article><article><b>Impostos e custos</b><p>Compare o rendimento líquido, considerando IR, IOF, custódia, taxas e prazo.</p></article><article><b>Objetivo e prazo</b><p>Dinheiro da reserva de emergência pede acesso e estabilidade, não apenas uma taxa maior.</p></article></div></section>'+
 '<section class="panel investment-learning"><div class="panel-head"><div><p class="eyebrow">GUIA PARA COMEÇAR</p><h2>Entenda antes de investir</h2><p>Um pequeno dicionário para quem está começando.</p></div></div><div class="investment-learning-grid"><article><b>Selic</b><p>É a taxa básica de juros da economia brasileira, definida pelo Copom. Ela influencia o custo do crédito e a rentabilidade de vários investimentos de renda fixa.</p></article><article><b>CDI</b><p>É uma taxa de referência muito próxima da Selic, usada para comparar investimentos. Quando um CDB paga 100% do CDI, sua remuneração acompanha essa referência, conforme as regras do produto.</p></article><article><b>IPCA</b><p>É o índice oficial de inflação ao consumidor. Ele mede como os preços variam e ajuda a entender se o rendimento está preservando seu poder de compra.</p></article><article><b>CDB</b><p>É um título emitido por um banco. Você empresta dinheiro à instituição e recebe juros. Confira taxa, vencimento, liquidez e risco do emissor. CDB elegível pode contar com cobertura do FGC, dentro dos limites e regras.</p></article><article><b>Tesouro Direto</b><p>É um programa de compra e venda de títulos públicos federais. Tesouro Selic costuma ser usado para objetivos de curto prazo, mas pode ter custos e regras de resgate; outros títulos oscilam de preço antes do vencimento.</p></article><article><b>Poupança</b><p>É uma aplicação simples e isenta de IR para pessoa física, com rendimento definido por regra legal. Compare sempre com alternativas de risco e liquidez semelhantes.</p></article><article><b>Liquidez</b><p>Indica a facilidade e o prazo para transformar o investimento em dinheiro disponível. Liquidez diária não significa necessariamente resgate instantâneo ou em qualquer horário.</p></article><article><b>FGC</b><p>O Fundo Garantidor de Créditos protege determinados produtos e depósitos elegíveis, respeitando limites por CPF/CNPJ e instituição ou conglomerado. Não cobre todo tipo de investimento.</p></article><article><b>Rendimento bruto e líquido</b><p>O bruto é antes de impostos e custos. O líquido é o que sobra depois deles. Para comparar opções, olhe o líquido e considere também a inflação.</p></article></div><p class="investment-note">Comece entendendo seu objetivo e mantendo uma reserva de emergência acessível. Nenhuma taxa isolada garante que um investimento seja adequado para você.</p></section>'+'<section class="investment-sources"><b>Fontes e metodologia</b><p>Indicadores consultados automaticamente no Sistema Gerenciador de Séries Temporais do Banco Central. Atualização ao abrir a área, no máximo uma vez a cada 24 horas; atualização manual disponível. As séries podem ter datas de referência diferentes.</p><a href="https://dadosabertos.bcb.gov.br/dataset/432-taxa-de-juros---meta-selic-definida-pelo-copom" target="_blank" rel="noopener">Banco Central · Meta Selic</a><a href="https://dadosabertos.bcb.gov.br/" target="_blank" rel="noopener">Banco Central · Dados abertos</a><a href="https://data.anbima.com.br/" target="_blank" rel="noopener">ANBIMA Data · consulta de ativos</a><p>Esta primeira versão não lista ofertas comerciais de CDB/LCI/LCA em tempo real. A taxa de CDB é um campo de simulação, não uma oferta verificada. Dados não são recomendação personalizada.</p></section>';
 setTimeout(updateInvestmentProjection,0);return view;
}
function render(){applyPreferences();document.body.classList.toggle('privacy-hidden',!privacyVisible);$('#sidebar-profile').innerHTML='<button type="button" class="profile-main-button" data-action="account-center"><span class="avatar">'+(S.profile?.foto?'<img src="'+esc(S.profile.foto)+'" alt="Foto de perfil" onerror="this.style.display=\'none\'">':'C')+'</span><span><strong>'+esc(S.profile?.chamado||'Caio')+'</strong><small>Meu perfil · informações pessoais</small></span></button><button type="button" class="profile-finance-button" data-action="edit-financial-profile" title="Configurar dados financeiros" aria-label="Configurar dados financeiros">−</button>';let nav=[['painel','Visão geral','▦'],['calendario','Calendário','▦'],['metas','Planos e metas','◎'],['assinaturas','Assinaturas','↻'],['planejamento','Planejamento','▦'],['bancos','Bancos e contas','◈'],['projecao','Projeção anual','▤'],['investimentos','Investimentos','↗']],moreNav=[['entradas','Entradas','＋'],...(S.preferences?.showMoto?[['moto','Minha moto','🏍']]:[]),['dividas','Dívidas','↘']];$('#tabs').innerHTML='<div class="nav-group"><span class="nav-label">MENU PRINCIPAL</span>'+nav.map(([k,l,ic])=>'<button class="nav-item '+(cur===k?'active':'')+'" data-action="'+(k==='painel'?'go-panel':'go-'+k)+'"><span class="nav-icon">'+ic+'</span>'+l+'</button>').join('')+'<button type="button" class="nav-more-toggle '+(showMoreNav?'expanded':'')+'" data-action="toggle-more-nav" aria-expanded="'+showMoreNav+'"><span class="nav-more-plus">'+(showMoreNav?'−':'+')+'</span><span>Mais</span><span class="nav-more-chevron">'+(showMoreNav?'⌃':'⌄')+'</span></button>'+(showMoreNav?'<div class="nav-more-items">'+moreNav.map(([k,l,ic])=>'<button class="nav-item '+(cur===k?'active':'')+'" data-action="go-'+k+'"><span class="nav-icon">'+ic+'</span>'+l+(k==='dividas'?'<b class="count">'+(privacyVisible?S.debts.filter(d=>d.valor>0).length:'••')+'</b>':'')+'</button>').join('')+'</div>':'')+'</div><div class="nav-status">● Salvamento local ativo</div>';$('#app').innerHTML='<button type="button" class="privacy-toggle" data-action="toggle-privacy" aria-label="'+(privacyVisible?'Ocultar valores':'Mostrar valores')+'" title="'+(privacyVisible?'Ocultar valores':'Mostrar valores')+'">'+(privacyVisible?'◉':'◎')+' <span>'+(privacyVisible?'Ocultar valores':'Mostrar valores')+'</span></button>'+(cur==='painel'?panelView():cur==='calendario'?calendarView():cur==='dividas'?debtView():cur==='metas'?goalsView():cur==='assinaturas'?subscriptionsView():cur==='planejamento'?planningView():cur==='bancos'?banksView():cur==='entradas'?entriesView():cur==='moto'?(S.preferences?.showMoto?motoView():panelView()):cur==='projecao'?annualView():cur==='investimentos'?investmentsView():monthView(cur))+'';let oldAdvisor=document.getElementById('advisor-fab');if(oldAdvisor)oldAdvisor.remove();let advisor=document.createElement('button');advisor.type='button';advisor.id='advisor-fab';advisor.className='advisor-fab';advisor.setAttribute('aria-label','Abrir conselheiro financeiro');advisor.title='Conselheiro financeiro';advisor.textContent='🤖';advisor.addEventListener('click',openSpendingAdvisor);document.body.appendChild(advisor);}function go(k){cur=k;render();if(k==='investimentos')refreshInvestmentRates().then(()=>{if(cur==='investimentos'){render();}});scrollTo({top:0,behavior:'smooth'})}
function upd(k,key,i,f,v){let r=M(k)[key][i],t=cols[key].find(c=>c[0]===f)[2];r[f]=t==='n'||t==='d'?(+v||0):v;save();render()}
function setM(k,f,v){let m=M(k);m[f]=Math.max(0,+v||0);if(f==='salary')m.salaryManual=true;save();render()}
function setEsp(k,c,v){M(k).esperado[c]=Math.max(0,+v||0);save();render()}
function addRow(k,key){let r={nome:'',dia:1,tipo:'Débito',cat:S.cats[0]||'Outros',bancoId:'',valor:0};if(key==='fixos')r.pago=false;if(key==='parcelas')r.parc='1/1';M(k)[key].push(r);save();render()}
function newMonth(){let k=(prompt('Informe o mês no formato AAAA-MM (ex.: 2027-11):','')||'').trim();if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(k))return alert('Use o formato AAAA-MM, como 2027-11.');if(S.months[k])return alert('Esse mês já existe.');let[y,m]=k.split('-');S.months[k]={salary:+S.profile?.salarioBase||0,salaryManual:false,bonus:+S.profile?.bonusBase||0,gastos:[],fixos:[],parcelas:[],reserva:0,rendaFixa:0,esperado:{},nomeMes:''};S.keys.push(k);S.keys=[...new Set(S.keys)].sort();let nome=(prompt('Nome para exibir (opcional):',new Date(+y,+m-1,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'}))||'').trim();if(nome)S.months[k].nomeMes=nome;cur=k;save();render()}
function renameMonth(k){let name=prompt('Nome que deseja exibir para este mês:',M(k).nomeMes||full(k));if(name===null)return;M(k).nomeMes=name.trim();save();render()}
function duplicateMonth(source){let target=(prompt('Qual mês receberá a cópia? Use AAAA-MM:', '')||'').trim();if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(target))return alert('Use o formato AAAA-MM, como 2027-11.');if(S.months[target])return alert('Esse mês já existe. Escolha outro mês.');let src=M(source),[y,m]=target.split('-');S.months[target]={...clone(src),nomeMes:'',gastos:clone(src.gastos||[]),fixos:(src.fixos||[]).map(r=>({...r,pago:false})),parcelas:clone(src.parcelas||[]),esperado:clone(src.esperado||{})};S.keys.push(target);S.keys=[...new Set(S.keys)].sort();let name=(prompt('Nome para exibir (opcional):',new Date(+y,+m-1,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'}))||'').trim();if(name)S.months[target].nomeMes=name;cur=target;save();render()}
function deleteMonth(k){if(S.keys.length<=1)return alert('Mantenha pelo menos um mês.');if(!confirm('Excluir '+full(k)+' e todos os seus lançamentos? Esta ação não pode ser desfeita.'))return;delete S.months[k];S.keys=S.keys.filter(x=>x!==k);cur='painel';save();render()}
function generateInstallments(k){let rows=M(k).parcelas.filter(r=>/^[ ]*[0-9]+[ ]*\/[ ]*[0-9]+[ ]*$/.test(String(r.parc||''))&&r.nome&&(+r.valor||0)>0);if(!rows.length)return alert('Preencha descrição, valor e parcela no formato 1/12.');let created=0;rows.forEach(r=>{let [n,total]=String(r.parc).split('/').map(v=>parseInt(v.trim(),10));if(!n||!total||n>=total)return;let [y,mo]=k.split('-').map(Number);for(let part=n+1;part<=total;part++){mo++;if(mo>12){mo=1;y++}let next=y+'-'+String(mo).padStart(2,'0');if(!S.months[next])S.months[next]={salary:+S.profile?.salarioBase||0,salaryManual:false,bonus:+S.profile?.bonusBase||0,gastos:[],fixos:[],parcelas:[],reserva:0,rendaFixa:0,esperado:{},aportesMetas:[]};if(!S.months[next].parcelas.some(x=>x.nome===r.nome+' (parcela '+part+'/'+total+')')){S.months[next].parcelas.push({...clone(r),nome:r.nome+' (parcela '+part+'/'+total+')',parc:part+'/'+total});created++}}});S.keys=[...new Set(S.keys)].sort();save();render();alert(created+' parcela(s) criada(s) nos meses seguintes.')}
function copyPrev(k){let i=S.keys.indexOf(k),p=S.months[S.keys[i-1]],m=M(k);if(!p)return alert('Não há mês anterior.');if(!confirm('Copiar contas fixas e parcelas do mês anterior?'))return;p.fixos.forEach(r=>m.fixos.push({...r,pago:false}));p.parcelas.forEach(r=>{let[a,b]=String(r.parc||'').split('/').map(Number);if(a&&b&&a<b)m.parcelas.push({...r,parc:(a+1)+'/'+b})});save();render()}
function exportData(){let a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify(S,null,2)],{type:'application/json'}));a.href=u;a.download='financas-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function importData(e){let f=e.target.files?.[0];if(!f)return;try{let j=JSON.parse(await f.text());if(!valid(j))throw 0;if(!confirm('Importar substituirá os dados deste navegador. Você já exportou um backup atual?'))return;S=normalize(j);cur='painel';save();render();alert('Backup importado.')}catch(e){alert('Arquivo inválido ou incompatível. Nenhum dado foi importado.')}finally{e.target.value=''}}
function restore(){if(confirm('Isso substituirá os dados atuais pelos dados iniciais. Exporte um backup antes. Continuar?')){S=normalize(clone(window.SEED));cur='painel';save();render()}}
function generateDebtInstallments(d){S.keys.forEach(k=>{if(S.months[k]){S.months[k].parcelas=(S.months[k].parcelas||[]).filter(x=>x.debtId!==d.id);S.months[k].fixos=(S.months[k].fixos||[]).filter(x=>x.debtId!==d.id)}});if(d.incluirPlano===false)return;const ensureMonth=k=>{if(!S.months[k]){S.months[k]={salary:+S.profile?.salarioBase||0,salaryManual:false,bonus:+S.profile?.bonusBase||0,gastos:[],fixos:[],parcelas:[],reserva:0,rendaFixa:0,esperado:{},aportesMetas:[]};S.keys.push(k)}};if(!d.parcelada){if(!/^\d{4}-\d{2}-\d{2}$/.test(d.dataVencimento||''))return;let dt=new Date(d.dataVencimento+'T12:00:00'),k=dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0');ensureMonth(k);S.months[k].fixos.push({debtId:d.id,nome:d.nome,tipo:d.formaPagamento||'Boleto',cat:d.cat||'Dívidas',bancoId:d.bancoId||'',valor:+d.valor||0,dia:dt.getDate(),pago:false});S.keys=[...new Set(S.keys)].sort();return}if(!d.totalParcelas||!d.valorParcela||!/^\d{4}-\d{2}-\d{2}$/.test(d.dataInicio||''))return;let start=new Date(d.dataInicio+'T12:00:00'),count=Math.min(360,+d.totalParcelas||0);for(let i=0;i<count;i++){let dt=debtDueDate(start.getFullYear(),start.getMonth()+i,Math.min(28,+d.dia||start.getDate())),k=dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0');ensureMonth(k);S.months[k].parcelas.push({debtId:d.id,nome:d.nome,tipo:d.formaPagamento||'Débito',cat:d.cat||'Dívidas',bancoId:d.bancoId||'',valor:+d.valorParcela||0,dia:dt.getDate(),parc:(i+1)+'/'+count,pago:false})}S.keys=[...new Set(S.keys)].sort()}
function editDebt(i){let d=S.debts[i];openForm('Editar dívida',debtFields(),{...d,parcelada:d.parcelada?'1':'0',negativada:d.negativada?'1':'0',incluirPlano:d.incluirPlano===false?'0':'1'},v=>{Object.assign(d,v,{cat:debtCategory(v.tipoDivida),valor:+v.valor||0,inicial:+v.inicial||+v.valor||0,parcelada:v.parcelada==='1',valorParcela:+v.valorParcela||0,totalParcelas:+v.totalParcelas||0,dia:+v.dia||10,negativada:v.negativada==='1',incluirPlano:v.incluirPlano!=='0'});d.vencimento=String(d.dia);d.dataVencimento=v.dataVencimento||d.dataVencimento||'';generateDebtInstallments(d);save();render()})}
function payDebt(i){let d=S.debts[i];if(!d)return;let todayDate=new Date().toISOString().slice(0,10);openForm('Registrar pagamento',[{type:'section',label:'01 · PAGAMENTO'},{name:'valor',label:'Valor pago (R$)',type:'number',min:.01,max:d.valor,step:'.01',required:true},{name:'data',label:'Data do pagamento',type:'date',required:true},{name:'bancoId',label:'Banco utilizado',type:'select',options:[{value:'',label:'Não informado'}].concat(S.banks.map(b=>({value:b.id,label:b.nome})))},{type:'section',label:'02 · DETALHES'},{name:'nota',label:'Observação (opcional)',type:'textarea'}],{valor:'',data:todayDate,bancoId:'',nota:''},v=>{let amount=+v.valor;if(!Number.isFinite(amount)||amount<=0){alert('Informe um valor válido maior que zero.');return false}if(amount>d.valor&&!confirm('O pagamento supera o saldo devedor. Registrar o valor e quitar a dívida?'))return false;amount=Math.min(amount,d.valor);d.historico=Array.isArray(d.historico)?d.historico:[];d.historico.push({valor:amount,data:v.data||todayDate,bancoId:v.bancoId||'',nota:v.nota||''});d.valor=Math.max(0,Math.round((d.valor-amount)*100)/100);save();return true})}
function deleteDebt(i){let d=S.debts[i];if(!d)return;let promptText='Excluir a dívida "'+d.nome+'"?';if(d.parcelada)promptText+=' As parcelas geradas no planejamento mensal também serão removidas.';promptText+=' Os registros de pagamentos desta dívida serão excluídos. Esta ação não pode ser desfeita.';if(!confirm(promptText))return;let id=d.id;S.debts.splice(i,1);S.keys.forEach(k=>{let m=S.months[k];if(m){if(Array.isArray(m.parcelas))m.parcelas=m.parcelas.filter(p=>p.debtId!==id);if(Array.isArray(m.fixos))m.fixos=m.fixos.filter(p=>p.debtId!==id)}});let dlg=document.getElementById('debt-detail-dialog');if(dlg)dlg.remove();save();render()}function removePayment(i,j){if(!confirm('Excluir o pagamento e devolver o valor ao saldo devedor?'))return;let p=S.debts[i].historico.splice(j,1)[0];S.debts[i].valor=Math.round((S.debts[i].valor+(+p.valor||0))*100)/100;save();render()}
function clickAction(b){let a=b.dataset.action;switch(a){case'toggle-privacy':privacyVisible=!privacyVisible;render();break;case'toggle-table-expand':expandedTable=expandedTable===b.dataset.table?'':b.dataset.table;render();break;case'clear-financial-registrations':clearFinancialRegistrations();break;case'toggle-more-nav':showMoreNav=!showMoreNav;render();break;case'calendar-day':{let date=b.dataset.date,[yy,mm,dd]=date.split('-').map(Number),kk=yy+'-'+String(mm).padStart(2,'0'),mo=S.months[kk]||{gastos:[],fixos:[],parcelas:[]},ev=['gastos','fixos','parcelas'].flatMap(key=>(mo[key]||[]).map((x,index)=>({...x,tipo:key==='gastos'?'Gasto':key==='fixos'?'Conta fixa':'Parcela',sourceKey:key,month:kk,index}))).filter(x=>dateKey(rowDueDate(kk,x))===date);(S.subscriptions||[]).filter(x=>x.ativo!==false&&(!x.inicio||kk>=x.inicio)&&dateKey(subscriptionDueDate(yy,mm-1,x))===date).forEach(x=>{if(!ev.some(e=>e.nome===x.nome))ev.push({nome:x.nome,valor:x.valor,tipo:x.regraVencimento==='5º dia útil'?'Assinatura · 5º dia útil':'Assinatura prevista',pago:false})});ev.push(...salaryBenefitEvents(yy,mm-1,dd,mo));ev=ev.filter(x=>calendarFilter==='todas'||calendarKind(x)===calendarFilter);showCalendarDay(date,ev);break;}case'go-panel':go('painel');break;case'edit-profile':editProfile();break;case'account-center':accountCenter('personal');break;case'edit-financial-profile':accountCenter('financial');break;case'advisor-open':openSpendingAdvisor();break;case'new-bonus':newBonus(b.dataset.month||cur);break;case'edit-bonus':editBonus(b.dataset.month||cur,+b.dataset.index);break;case'delete-bonus':deleteBonus(b.dataset.month||cur,+b.dataset.index);break;case'export-csv':exportCSV();break;case'export-pdf':exportPDF();break;case'clear-all-months':clearAllMonths();break;case'go-calendario':go('calendario');break;case'calendar-prev':calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()-1,1);render();break;case'calendar-next':calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()+1,1);render();break;case'calendar-filter':calendarFilter=b.dataset.filter||'todas';render();break;case'go-projecao':go('projecao');break;case'go-debts':case'go-dividas':go('dividas');break;case'go-metas':go('metas');break;case'go-assinaturas':go('assinaturas');break;case'go-planejamento':go('planejamento');break;case'go-bancos':go('bancos');break;case'go-entradas':go('entradas');break;case'go-moto':go('moto');break;case'moto-add-expense':addMotoExpense();break;case'new-entry':newEntry();break;case'edit-entry':editEntry(b.dataset.id);break;case'delete-entry':if(confirm('Excluir esta entrada?')){S.movements=S.movements.filter(x=>x.id!==b.dataset.id);save();render()}break;case'goal-detail':goalDetail(b.dataset.id);break;case'go-projecao':go('projecao');break;case'go-investimentos':go('investimentos');break;case'refresh-investments':refreshInvestmentRates(true);break;case'delete-month':deleteMonth(b.dataset.month||cur);break;case'generate-installments':generateInstallments(b.dataset.month||cur);break;case'new-goal':newGoal('',b.dataset.goalType||'');break;case'new-child-goal':newGoal(b.dataset.id,'Meta');break;case'edit-goal':editGoal(b.dataset.id);break;case'new-investment':newInvestment(b.dataset.month||cur);break;case'add-vr-period':addVrPeriod(b.dataset.month||cur);break;case'delete-vr-period':deleteVrPeriod(b.dataset.month||cur,+b.dataset.index);break;case'delete-investment':if(confirm('Excluir este investimento do planejamento mensal?')){M(b.dataset.month||cur).investimentos.splice(+b.dataset.index,1);save();render()}break;case'delete-goal':if(confirm('Excluir esta meta?')){S.goals=S.goals.filter(g=>g.id!==b.dataset.id);save();render()}break;case'new-bank':newBank();break;case'edit-bank':editBank(b.dataset.id);break;case'delete-bank':if(confirm('Excluir esta conta?')){S.banks=S.banks.filter(x=>x.id!==b.dataset.id);save();render()}break;case'new-subscription':newSubscription();break;case'edit-subscription':editSubscription(+b.dataset.index);break;case'delete-subscription':deleteSubscription(+b.dataset.index);break;case'apply-subscriptions':applySubscriptions();break;case'add-goal-contribution':addGoalContribution(b.dataset.month||cur);break;case'go-current':go(S.keys.includes(today)?today:S.keys[0]);break;case'go-month':go(b.dataset.month);break;case'new-month':newMonth();break;case'rename-month':renameMonth(b.dataset.month||cur);break;case'duplicate-month':duplicateMonth(b.dataset.month||cur);break;case'clear-date-filter':dateFilter={from:'',to:''};render();break;case'delete-month':deleteMonth(b.dataset.month||cur);break;case'add-goal-contribution':addGoalContribution(b.dataset.month||cur);break;case'add-row':addRow(b.dataset.month,b.dataset.key);break;case'delete-row':if(confirm('Excluir este lançamento?')){M(b.dataset.month)[b.dataset.key].splice(+b.dataset.index,1);save();render()}break;case'copy-prev':copyPrev(b.dataset.month);break;case'new-cat':{let n=(prompt('Nome da nova categoria:')||'').trim();if(n&&!S.cats.includes(n)){S.cats.push(n);save();render()}break}case'export':exportData();break;case'import':$('#file').click();break;case'restore':restore();break;case'manage-debt-types':manageDebtTypes();break;case'new-debt':newDebt();break;case'edit-debt':editDebt(+b.dataset.index);break;case'detail-debt':debtDetail(+b.dataset.index);break;case'pay-debt':payDebt(+b.dataset.index);break;case'history':{let el=$('#history-'+b.dataset.index);if(el)el.hidden=!el.hidden;break}case'remove-payment':removePayment(+b.dataset.index,+b.dataset.payment);break;case'delete-debt':deleteDebt(+b.dataset.index);break;case'filter':filter=b.dataset.filter;render();break}}
$('#tabs').addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(b)clickAction(b);if(innerWidth<=620){$('#sidebar').classList.remove('mobile-open');$('#nav-overlay').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false')}});$('#menu-toggle').addEventListener('click',()=>{let open=$('#sidebar').classList.toggle('mobile-open');$('#nav-overlay').hidden=!open;$('#menu-toggle').setAttribute('aria-expanded',String(open))});$('#nav-overlay').addEventListener('click',()=>{$('#sidebar').classList.remove('mobile-open');$('#nav-overlay').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false')});
let draggedDebtIndex=null;$('#app').addEventListener('dragstart',e=>{let card=e.target.closest('[data-debt-drag]');if(!card)return;draggedDebtIndex=+card.dataset.debtDrag;card.classList.add('debt-dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(draggedDebtIndex))});$('#app').addEventListener('dragend',e=>{e.target.closest('[data-debt-drag]')?.classList.remove('debt-dragging');document.querySelectorAll('.debt-drop-target').forEach(x=>x.classList.remove('debt-drop-target'));draggedDebtIndex=null});$('#app').addEventListener('dragover',e=>{let card=e.target.closest('[data-debt-drag]');if(card&&draggedDebtIndex!==null){e.preventDefault();card.classList.add('debt-drop-target')}});$('#app').addEventListener('dragleave',e=>{e.target.closest('[data-debt-drag]')?.classList.remove('debt-drop-target')});$('#app').addEventListener('drop',e=>{let card=e.target.closest('[data-debt-drag]');if(!card||draggedDebtIndex===null)return;e.preventDefault();let from=draggedDebtIndex,to=+card.dataset.debtDrag;if(from===to)return;let item=S.debts.splice(from,1)[0];S.debts.splice(to,0,item);S.debts.forEach((d,i)=>d.prioridade=i);save();render()});$('#app').addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(b)clickAction(b)});
$('#app').addEventListener('change',e=>{let el=e.target,d=el.dataset;if(d.change==='investment-input'){updateInvestmentProjection()}else if(d.change==='month')setM(d.month,d.field,el.value);else if(d.change==='expected')setEsp(d.month,d.category,el.value);else if(d.change==='row')upd(d.month,d.key,+d.index,d.field,el.type==='checkbox'?el.checked:el.value);else if(d.change==='date-filter'){dateFilter[d.field]=el.value;render()}else if(d.change==='projection-year'){projectionYear=+el.value;render()}else if(d.change==='investment-input'){updateInvestmentProjection()}else if(d.change==='bank-color'){let bank=S.banks.find(x=>x.id===d.id);if(bank){bank.cor=el.value;save();render()}}else if(d.change==='debt-status'){let debt=S.debts[+d.index];if(debt){if(d.field==='negativada')debt.negativada=el.value==='1';else if(d.field==='incluirPlano'){debt.incluirPlano=el.value==='1';generateDebtInstallments(debt)}else if(d.field==='statusNegociacao')debt.statusNegociacao=el.value;save();render()}}});
